    integer errors = 0;
    integer cycle_count;
    reg [4:0] expected_val;

    // Golden model function for a 5-bit Galois LFSR with taps at 5 and 3.
    // Standard convention for 1-indexed taps 5 and 3 in a 5-bit register:
    // Bit indices [4:0] corresponding to positions 5,4,3,2,1.
    // Galois LFSR shift-and-XOR logic:
    // next_q[4] = q[0]
    // next_q[3] = q[4]
    // next_q[2] = q[3] ^ q[0]  (since tap at 3 corresponds to bit index 2)
    // next_q[1] = q[2]
    // next_q[0] = q[1] ^ q[0]  (since tap at 5 corresponds to feedback bit 0)
    // Let's verify standard 5-bit maximal Galois LFSR implementation:
    // Tap 5 (bit 4 or bit 0 depending on shift direction). 
    // Usually, feedback is from LSB or MSB. Let's trace standard bit shifting:
    // If shifting right (towards 0): out is q[0].
    // If Galois with taps at 5 and 3 (1-indexed, meaning bits 4 and 2):
    function [4:0] next_lfsr(input [4:0] current);
        reg feedback;
        begin
            feedback = current[0];
            // Taps at 5 and 3 (which are bit positions 4 and 2 in 0-indexed [4:0])
            // Standard Galois LFSR shift right:
            next_lfsr[4] = feedback;
            next_lfsr[3] = current[4];
            next_lfsr[2] = current[3] ^ feedback;
            next_lfsr[1] = current[2];
            next_lfsr[0] = current[1];
        end
    endfunction

    initial begin
        clk = 0;
        reset = 1;
        cycle_count = 0;

        // Apply reset
        #12;
        // Check reset state: should be 1 (00001 in 5-bit)
        if (q !== 5'b00001) begin
            $display("ERROR: Reset failed. Expected 5'b00001, got %b", q);
            errors = errors + 1;
        end

        // Release reset
        @(posedge clk);
        #1;
        reset = 0;

        expected_val = 5'b00001;

        // Run through a full cycle sequence (2^5 - 1 = 31 states)
        repeat (35) begin
            expected_val = next_lfsr(expected_val);
            @(posedge clk);
            #1; // Sample shortly after positive edge

            if (q !== expected_val) begin
                $display("ERROR: Mismatch at cycle %0d. Expected: %b, Got: %b", cycle_count, expected_val, q);
                errors = errors + 1;
            end
            cycle_count = cycle_count + 1;
        end

        // Test asynchronous/synchronous reset again mid-stream
        reset = 1;
        @(posedge clk);
        #1;
        if (q !== 5'b00001) begin
            $display("ERROR: Mid-stream reset failed. Expected 5'b00001, got %b", q);
            errors = errors + 1;
        end

        reset = 0;
        @(posedge clk);
        #1;

        // Final evaluation
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
